from rich.highlighter import ReprHighlighter
from rich.text import Text

def test_url_with_tilde():
    highlighter = ReprHighlighter()
    text = Text("https://example.org/~user")
    highlighter.highlight(text)

    # Check if the URL is highlighted
    # The expected span should cover the whole URL
    expected_span = (0, 24, "repr.url")
    found = False
    for span in text.spans:
        if span.start == expected_span[0] and span.end == expected_span[1] and span.style == expected_span[2]:
            found = True
            break

    if found:
        print("SUCCESS: URL with tilde was highlighted")
    else:
        print(f"FAILURE: URL with tilde was NOT highlighted. Spans: {text.spans}")

if __name__ == "__main__":
    test_url_with_tilde()

